export declare const templateTheme = "/*\n * ============================================\n * WeMD \u4E3B\u9898\u6A21\u677F\n * ============================================\n * \n * \u4F7F\u7528\u8BF4\u660E\uFF1A\n * 1. \u4FEE\u6539\u4E0B\u65B9\u7684\u6837\u5F0F\u5B9A\u4E49\uFF0C\u521B\u5EFA\u4F60\u7684\u81EA\u5B9A\u4E49\u4E3B\u9898\n * 2. \u6240\u6709\u9009\u62E9\u5668\u5FC5\u987B\u4EE5 #wemd \u5F00\u5934\n * 3. \u4EE3\u7801\u5757\u4F7F\u7528 #wemd pre code.hljs\uFF0C\u4E0D\u8981\u8BBE\u7F6E\u5168\u5C40 color\n * \n * ============================================\n * \uD83C\uDF19 \u6DF1\u8272\u6A21\u5F0F\u8BF4\u660E\uFF08\u5FAE\u4FE1\u517C\u5BB9\uFF09\n * ============================================\n * \n * \u2705 \u652F\u6301\u81EA\u52A8\u8F6C\u6362\u7684\u989C\u8272\u683C\u5F0F\uFF1A\n *   - HEX: #333333, #fff\n *   - RGB: rgb(51, 51, 51), rgba(0, 0, 0, 0.5)\n *   - HSL: hsl(0, 0%, 20%), hsla(0, 0%, 0%, 0.5)\n *   - \u6E10\u53D8: linear-gradient(), radial-gradient() \u4E2D\u7684\u8272\u503C\n * \n * \uD83D\uDD04 \u667A\u80FD\u8F6C\u6362\u89C4\u5219\uFF08\u8272\u5F69\u8BED\u4E49\u4FDD\u5168\uFF09\uFF1A\n *   - \u7070\u5EA6\u80CC\u666F \u2192 \u6620\u5C04\u5230\u6DF1\u8272\u533A\u95F4 (10%-20% \u4EAE\u5EA6)\n *   - \u9AD8\u9971\u548C\u8272\u5F69 (S>15%) \u2192 \u4FDD\u6301\u9C9C\u8273\uFF0C\u4EAE\u5EA6\u94B3\u5236\u5728 35%-55%\n *   - \u6DF1\u8272\u9634\u5F71/\u8FB9\u6846 (L<20) \u2192 \u951A\u5B9A\u4E3A\u6697\u8272\uFF0C\u4E0D\u53CD\u8F6C\n *   - \u6587\u5B57\u989C\u8272 \u2192 \u52A8\u6001\u5BF9\u6BD4\u5EA6\u8C03\u6574\u4EE5\u4FDD\u8BC1\u53EF\u8BFB\u6027\n * \n * \u26A0\uFE0F \u4E0D\u4F1A\u88AB\u8F6C\u6362\uFF1A\n *   - CSS \u53D8\u91CF: var(--xxx)\n *   - \u56FE\u7247: url()\n *   - \u989C\u8272\u540D\u79F0: white, black\uFF08\u8BF7\u4F7F\u7528 HEX \u683C\u5F0F\uFF09\n * \n * \uD83D\uDCA1 \u8BBE\u8BA1\u5EFA\u8BAE\uFF1A\n *   - \u80CC\u666F\u8272\u7528\u900F\u660E\u6216\u6D45\u7070\uFF0C\u5229\u4E8E\u81EA\u52A8\u9002\u914D\n *   - \u5F69\u8272\u88C5\u9970\u4FDD\u6301\u539F\u503C\uFF0C\u7B97\u6CD5\u81EA\u52A8\u4FDD\u62A4\n *   - \u6DF1\u8272\u6295\u5F71\u548C\u7C97\u8FB9\u6846\u4F7F\u7528\u7EAF\u9ED1 #000\uFF0C\u53EF\u4FDD\u6301\u5C42\u7EA7\u611F\n */\n\n/* ============================================\n * 1. \u5168\u5C40\u5BB9\u5668\u6837\u5F0F\n * ============================================\n */\n#wemd {\n    padding: 30px 20px;\n    max-width: 677px;\n    margin: 0 auto;\n    font-family: -apple-system, BlinkMacSystemFont, \"Microsoft YaHei\", sans-serif;\n    color: #333;\n    background-color: transparent;\n    /* \u900F\u660E\u80CC\u666F\uFF0C\u517C\u5BB9\u5FAE\u4FE1\u6DF1\u8272\u6A21\u5F0F */\n    word-break: break-word;\n}\n\n/* ============================================\n * 2. \u6BB5\u843D\u6837\u5F0F\n * ============================================\n */\n#wemd p {\n    margin: 16px 0;\n    /* \u6BB5\u843D\u95F4\u8DDD\uFF1A\u4E0A\u4E0B\u5404 16px */\n    line-height: 1.7;\n    /* \u884C\u9AD8\uFF1A1.7 \u500D\uFF0C\u8212\u9002\u9605\u8BFB */\n    text-align: justify;\n    /* \u6587\u672C\u5BF9\u9F50\uFF1A\u4E24\u7AEF\u5BF9\u9F50 */\n    color: #333;\n    /* \u6587\u5B57\u989C\u8272 */\n    font-size: 16px;\n    /* \u5B57\u4F53\u5927\u5C0F */\n}\n\n/* ============================================\n * 3. \u6807\u9898\u6837\u5F0F\n * ============================================\n * \u6CE8\u610F\uFF1A\u6807\u9898\u5185\u90E8\u7ED3\u6784\u4E3A\uFF1A\n * <h1>\n *   <span class=\"prefix\"></span>\n *   <span class=\"content\">\u6807\u9898\u6587\u5B57</span>\n *   <span class=\"suffix\"></span>\n * </h1>\n * \n * \u53EF\u4EE5\u901A\u8FC7 .prefix \u548C .suffix \u6DFB\u52A0\u88C5\u9970\u5143\u7D20\n */\n\n/* \u4E00\u7EA7\u6807\u9898 */\n#wemd h1 {\n    margin: 40px 0 30px;\n    /* \u5916\u8FB9\u8DDD\uFF1A\u4E0A 40px\uFF0C\u4E0B 30px */\n    text-align: center;\n    /* \u5C45\u4E2D\u5BF9\u9F50 */\n}\n\n#wemd h1 .content {\n    font-size: 24px;\n    /* \u5B57\u4F53\u5927\u5C0F */\n    font-weight: bold;\n    /* \u5B57\u4F53\u7C97\u7EC6\uFF1A\u52A0\u7C97 */\n    color: #000;\n    /* \u6587\u5B57\u989C\u8272 */\n}\n\n/* \u9690\u85CF\u524D\u7F00\u548C\u540E\u7F00\uFF08\u5982\u679C\u4E0D\u9700\u8981\u88C5\u9970\uFF09 */\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n    display: none;\n}\n\n/* \u4E8C\u7EA7\u6807\u9898 */\n#wemd h2 {\n    margin: 30px 0 20px;\n}\n\n#wemd h2 .content {\n    font-size: 20px;\n    font-weight: bold;\n    color: #333;\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n    display: none;\n}\n\n/* \u4E09\u7EA7\u6807\u9898 */\n#wemd h3 {\n    margin: 25px 0 15px;\n}\n\n#wemd h3 .content {\n    font-size: 18px;\n    font-weight: bold;\n    color: #666;\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n    display: none;\n}\n\n/* \u56DB\u7EA7\u6807\u9898 */\n#wemd h4 {\n    margin: 20px 0 10px;\n}\n\n#wemd h4 .content {\n    font-size: 16px;\n    font-weight: bold;\n    color: #666;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n    display: none;\n}\n\n/* ============================================\n * 4. \u5F15\u7528\u6837\u5F0F\n * ============================================\n * \u652F\u6301\u591A\u7EA7\u5F15\u7528\uFF1A.multiquote-1, .multiquote-2, .multiquote-3\n */\n#wemd .multiquote-1 {\n    margin: 20px 0;\n    /* \u5916\u8FB9\u8DDD */\n    padding: 16px 20px;\n    /* \u5185\u8FB9\u8DDD */\n    background: #f5f5f5;\n    /* \u80CC\u666F\u8272 */\n    border-left: 4px solid #ddd;\n    /* \u5DE6\u8FB9\u6846 */\n    border-radius: 4px;\n    /* \u5706\u89D2 */\n}\n\n#wemd .multiquote-1 p {\n    margin: 0;\n    /* \u6BB5\u843D\u65E0\u5916\u8FB9\u8DDD */\n    color: #666;\n    /* \u6587\u5B57\u989C\u8272 */\n    font-size: 15px;\n}\n\n/* \u4E8C\u7EA7\u5F15\u7528 */\n#wemd .multiquote-2 {\n    margin: 18px 0;\n    padding: 14px 18px;\n    background: #fafafa;\n    border-left: 3px solid #ccc;\n}\n\n#wemd .multiquote-2 p {\n    margin: 0;\n    color: #777;\n    font-size: 14px;\n}\n\n/* \u4E09\u7EA7\u5F15\u7528 */\n#wemd .multiquote-3 {\n    margin: 16px 0;\n    padding: 12px 16px;\n    background: #fafafa;\n    border-left: 2px solid #bbb;\n}\n\n#wemd .multiquote-3 p {\n    margin: 0;\n    color: #888;\n    font-size: 14px;\n}\n\n/* ============================================\n * 5. \u5217\u8868\u6837\u5F0F\n * ============================================\n */\n#wemd ul,\n#wemd ol {\n    margin: 15px 0;\n    padding-left: 25px;\n    /* \u5DE6\u5185\u8FB9\u8DDD\uFF0C\u4E3A\u5217\u8868\u7B26\u53F7\u7559\u7A7A\u95F4 */\n}\n\n#wemd ul {\n    list-style-type: disc;\n    /* \u65E0\u5E8F\u5217\u8868\uFF1A\u5B9E\u5FC3\u5706\u70B9 */\n}\n\n#wemd ol {\n    list-style-type: decimal;\n    /* \u6709\u5E8F\u5217\u8868\uFF1A\u6570\u5B57 */\n}\n\n/* \u5217\u8868\u9879\u5185\u5BB9\n * \u6CE8\u610F\uFF1A\u5217\u8868\u9879\u5185\u90E8\u4F7F\u7528 <section> \u5305\u88F9\u5185\u5BB9\n */\n#wemd li section {\n    margin: 5px 0;\n    /* \u5217\u8868\u9879\u95F4\u8DDD */\n    color: #333;\n    /* \u6587\u5B57\u989C\u8272 */\n    line-height: 1.6;\n}\n\n#wemd ul ul {\n    list-style-type: circle;\n    margin-top: 6px;\n}\n\n#wemd ol ol {\n    list-style-type: lower-alpha;\n}\n\n/* ============================================\n * 6. \u94FE\u63A5\u6837\u5F0F\n * ============================================\n */\n#wemd a {\n    color: #1e6bb8;\n    /* \u94FE\u63A5\u989C\u8272 */\n    text-decoration: none;\n    /* \u53BB\u9664\u4E0B\u5212\u7EBF */\n    border-bottom: 1px solid #1e6bb8;\n    /* \u5E95\u90E8\u8FB9\u6846\u4F5C\u4E3A\u4E0B\u5212\u7EBF */\n    font-weight: bold;\n    /* \u52A0\u7C97 */\n}\n\n/* ============================================\n * 7. \u6587\u672C\u6837\u5F0F\n * ============================================\n */\n/* \u52A0\u7C97 */\n#wemd strong {\n    font-weight: bold;\n    color: #000;\n}\n\n/* \u659C\u4F53 */\n#wemd em {\n    font-style: italic;\n    color: #333;\n}\n\n/* \u52A0\u7C97\u659C\u4F53 */\n#wemd em strong {\n    font-weight: bold;\n    font-style: italic;\n    color: #000;\n}\n\n/* \u9AD8\u4EAE */\n#wemd mark {\n    background: #fff3cd;\n    color: #000;\n    padding: 2px 4px;\n    border-radius: 3px;\n}\n\n/* \u5220\u9664\u7EBF */\n#wemd del {\n    text-decoration: line-through;\n    color: #999;\n}\n\n/* ============================================\n * 8. \u884C\u5185\u4EE3\u7801\u6837\u5F0F\n * ============================================\n * \u6CE8\u610F\uFF1A\u884C\u5185\u4EE3\u7801\u5728\u6BB5\u843D\u548C\u5217\u8868\u9879\u4E2D\n */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n    color: #e83e8c;\n    /* \u6587\u5B57\u989C\u8272 */\n    background: #f8f9fa;\n    /* \u80CC\u666F\u8272 */\n    padding: 2px 6px;\n    /* \u5185\u8FB9\u8DDD */\n    margin: 0 2px;\n    /* \u5916\u8FB9\u8DDD */\n    border-radius: 3px;\n    /* \u5706\u89D2 */\n    font-size: 14px;\n    font-family: \"Courier New\", Courier, monospace;\n    /* \u7B49\u5BBD\u5B57\u4F53 */\n}\n\n/* ============================================\n * 9. \u4EE3\u7801\u5757\u6837\u5F0F\uFF08\u91CD\u8981\uFF01\uFF09\n * ============================================\n * \n * \u26A0\uFE0F \u91CD\u8981\u63D0\u793A\uFF1A\n * 1. \u5FC5\u987B\u4F7F\u7528 #wemd pre code.hljs \u9009\u62E9\u5668\uFF0C\u4E0D\u8981\u4F7F\u7528 #wemd pre code\n * 2. \u4E0D\u8981\u8BBE\u7F6E\u5168\u5C40 color \u5C5E\u6027\uFF0C\u8BA9\u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236\u6587\u5B57\u989C\u8272\n * 3. \u5982\u679C\u8BBE\u7F6E\u4E86 color\uFF0C\u4F1A\u8986\u76D6\u8BED\u6CD5\u9AD8\u4EAE\u7684\u989C\u8272\uFF0C\u5BFC\u81F4\u4EE3\u7801\u770B\u4E0D\u6E05\n * 4. \u4F7F\u7528 #wemd pre code:not(.hljs) \u4F5C\u4E3A\u540E\u5907\u6837\u5F0F\uFF08\u65E0\u8BED\u6CD5\u9AD8\u4EAE\u65F6\uFF09\n * \n * \u793A\u4F8B\uFF08\u6B63\u786E\uFF09\uFF1A\n * #wemd pre code.hljs {\n *     background: #f5f5f5;\n *     // \u4E0D\u8BBE\u7F6E color\n * }\n * \n * \u793A\u4F8B\uFF08\u9519\u8BEF\uFF09\uFF1A\n * #wemd pre code {\n *     color: #333;  // \u274C \u8FD9\u4F1A\u8986\u76D6\u8BED\u6CD5\u9AD8\u4EAE\n * }\n */\n#wemd pre code.hljs {\n    display: block;\n    padding: 16px;\n    /* \u5185\u8FB9\u8DDD */\n    background: #f5f5f5;\n    /* \u80CC\u666F\u8272 */\n    /* \u26A0\uFE0F \u6CE8\u610F\uFF1A\u4E0D\u8981\u5728\u8FD9\u91CC\u8BBE\u7F6E color\uFF0C\u8BA9\u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236 */\n    font-size: 13px;\n    line-height: 1.6;\n    border-radius: 4px;\n    /* \u5706\u89D2 */\n    font-family: \"Courier New\", \"Consolas\", \"Monaco\", monospace;\n    /* \u7B49\u5BBD\u5B57\u4F53 */\n    overflow-x: auto;\n    /* \u6A2A\u5411\u6EDA\u52A8 */\n    white-space: pre;\n  min-width: max-content;\n    /* \u4FDD\u7559\u7A7A\u767D\u548C\u6362\u884C */\n    border: 1px solid #ddd;\n    /* \u8FB9\u6846 */\n}\n\n/* \u5982\u679C\u6CA1\u6709\u8BED\u6CD5\u9AD8\u4EAE\uFF0C\u8BBE\u7F6E\u9ED8\u8BA4\u6837\u5F0F */\n#wemd pre code:not(.hljs) {\n    color: #333;\n    /* \u9ED8\u8BA4\u6587\u5B57\u989C\u8272 */\n    background: #f5f5f5;\n    border: 1px solid #ddd;\n}\n\n/* ============================================\n * 10. \u56FE\u7247\u6837\u5F0F\n * ============================================\n */\n#wemd img {\n    display: block;\n    /* \u5757\u7EA7\u5143\u7D20 */\n    margin: 20px auto;\n    /* \u5C45\u4E2D\uFF1A\u4E0A\u4E0B 20px\uFF0C\u5DE6\u53F3\u81EA\u52A8 */\n    max-width: 100%;\n    /* \u6700\u5927\u5BBD\u5EA6\uFF1A\u4E0D\u8D85\u51FA\u5BB9\u5668 */\n    border-radius: 4px;\n    /* \u5706\u89D2 */\n}\n\n/* \u56FE\u7247\u5BB9\u5668\uFF08figure\uFF09 */\n#wemd figure {\n    margin: 20px 0;\n    text-align: center;\n}\n\n/* \u56FE\u7247\u8BF4\u660E\u6587\u5B57\uFF08figcaption\uFF09 */\n#wemd figcaption {\n    margin-top: 8px;\n    color: #999;\n    font-size: 14px;\n}\n\n/* ============================================\n * 11. \u8868\u683C\u6837\u5F0F\n * ============================================\n */\n#wemd table {\n    width: 100%;\n    /* \u5BBD\u5EA6\uFF1A100% */\n    border-collapse: collapse;\n    /* \u8FB9\u6846\u5408\u5E76 */\n    margin: 20px 0;\n    /* \u5916\u8FB9\u8DDD */\n    font-size: 14px;\n}\n\n/* \u8868\u5934 */\n#wemd table tr th {\n    background: #f5f5f5;\n    /* \u80CC\u666F\u8272 */\n    color: #333;\n    border: 1px solid #ddd;\n    /* \u8FB9\u6846 */\n    padding: 10px;\n    /* \u5185\u8FB9\u8DDD */\n    font-weight: bold;\n    /* \u52A0\u7C97 */\n    text-align: left;\n}\n\n/* \u8868\u683C\u5355\u5143\u683C */\n#wemd table tr td {\n    border: 1px solid #ddd;\n    padding: 10px;\n    color: #333;\n}\n\n/* \u6591\u9A6C\u7EB9\uFF08\u9694\u884C\u53D8\u8272\uFF09 */\n#wemd table tr:nth-child(even) td {\n    background-color: #fafafa;\n}\n\n/* ============================================\n * 12. \u5206\u5272\u7EBF\u6837\u5F0F\n * ============================================\n */\n#wemd hr {\n    margin: 30px 0;\n    /* \u5916\u8FB9\u8DDD */\n    border: none;\n    /* \u53BB\u9664\u9ED8\u8BA4\u8FB9\u6846 */\n    border-top: 1px solid #ddd;\n    /* \u9876\u90E8\u8FB9\u6846 */\n    height: 1px;\n}\n\n/* ============================================\n * 13. \u811A\u6CE8\u6837\u5F0F\n * ============================================\n */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n    color: #1e6bb8;\n    /* \u811A\u6CE8\u94FE\u63A5\u989C\u8272 */\n    font-weight: bold;\n}\n\n#wemd .footnotes-sep {\n    border-top: 1px solid #ddd;\n    /* \u5206\u9694\u7EBF */\n    padding-top: 20px;\n    margin-top: 40px;\n}\n\n#wemd .footnote-num {\n    font-weight: bold;\n    color: #1e6bb8;\n    margin-right: 4px;\n}\n\n#wemd .footnote-item p {\n    color: #666;\n    font-size: 14px;\n    margin: 4px 0;\n}\n\n/* ============================================\n * 14. \u6570\u5B66\u516C\u5F0F\u6837\u5F0F\n * ============================================\n */\n/* \u884C\u95F4\u516C\u5F0F */\n#wemd .block-equation {\n    display: block;\n    text-align: center;\n    margin: 20px 0;\n    overflow-x: auto;\n}\n\n#wemd .block-equation > svg {\n    max-width: 100% !important;\n    /* \u6700\u5927\u5BBD\u5EA6\uFF1A\u4E0D\u8D85\u51FA\u5BB9\u5668 */\n}\n\n/* \u884C\u5185\u516C\u5F0F */\n#wemd .inline-equation {\n    display: inline;\n}\n\n#wemd .inline-equation > svg {\n    max-width: 100%;\n    vertical-align: middle;\n    /* \u5782\u76F4\u5C45\u4E2D */\n}\n\n/* ============================================\n * 16. \u63D0\u793A\u5757\u6837\u5F0F\uFF08Callout\uFF09\n * ============================================\n * \n * \u63D0\u793A\u5757\u7528\u4E8E\u663E\u793A\u4E0D\u540C\u7C7B\u578B\u7684\u63D0\u793A\u4FE1\u606F\n * \u652F\u6301\u7684\u7C7B\u578B\uFF1Anote\u3001info\u3001tip\u3001success\u3001warning\u3001danger\n */\n\n/* \u63D0\u793A\u5757\u57FA\u7840\u6837\u5F0F */\n#wemd .callout {\n    margin: 20px 0;\n    padding: 16px 20px;\n    background: #f5f5f5;\n    border-left: 4px solid #ddd;\n    border-radius: 4px;\n}\n\n#wemd .callout-title {\n    font-weight: bold;\n    margin-bottom: 8px;\n    color: #333;\n    font-size: 15px;\n}\n\n#wemd .callout-icon { margin-right: 8px;\n    margin-right: 6px;\n}\n\n/* \u4E0D\u540C\u7C7B\u578B\u7684\u63D0\u793A\u5757 */\n#wemd .callout-note { \n    border-left-color: #6366f1; \n    background: #f5f5ff; \n}\n\n#wemd .callout-tip { \n    border-left-color: #10b981; \n    background: #ecfdf5; \n}\n\n#wemd .callout-important { \n    border-left-color: #8b5cf6; \n    background: #f5f3ff; \n}\n\n#wemd .callout-warning { \n    border-left-color: #f59e0b; \n    background: #fffbeb; \n}\n\n#wemd .callout-caution { \n    border-left-color: #ef4444; \n    background: #fff5f5; \n}\n\n/* ============================================\n * 15. \u5176\u4ED6\u5143\u7D20\n * ============================================\n */\n/* \u5B9A\u4E49\u5217\u8868 */\n#wemd dl {\n    margin: 15px 0;\n}\n\n#wemd dt {\n    font-weight: bold;\n    margin-top: 10px;\n}\n\n#wemd dd {\n    margin-left: 20px;\n    color: #666;\n}\n\n/* \u76EE\u5F55\uFF08TOC\uFF09 */\n#wemd .table-of-contents {\n    margin: 20px 0;\n    padding: 15px;\n    background: #f5f5f5;\n    border-left: 3px solid #ddd;\n    border-radius: 4px;\n}\n\n#wemd .table-of-contents a {\n    color: #333;\n    text-decoration: none;\n}\n\n\n\n\n/* ============================================\n * 17. \u56FE\u7247\u8F6E\u64AD\u6837\u5F0F (Imageflow)\n * ============================================\n */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  /* white-space: normal; */\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
